<?php

declare(strict_types=1);

/** Hold the endpoint and signing secret of a signed webhook channel. */

namespace App\Data\Notifications;

use App\Contracts\Notifications\ChannelConfiguration;
use App\Enums\Notifications\ChannelType;

/**
 * The URL may embed a customer token in its path or query, so it is treated as secret. The signing secret is
 * generated by the server and revealed only once through a dedicated rotation response.
 */
final readonly class WebhookChannelConfiguration implements ChannelConfiguration
{
    /**
     * @param string $url Normalized absolute HTTPS URL; SSRF checks run again at delivery time.
     * @param string $signingSecret 256-bit hexadecimal HMAC key.
     */
    public function __construct(public string $url, public string $signingSecret)
    {
    }

    /** @return ChannelType Always webhook. */
    public function type(): ChannelType
    {
        return ChannelType::Webhook;
    }

    /** @return array{url: string, signing_secret: string} Persisted endpoint and key. */
    public function toArray(): array
    {
        return ['url' => $this->url, 'signing_secret' => $this->signingSecret];
    }

    /** @return string Scheme and host only; path and query may carry tokens. */
    public function hint(): string
    {
        $host = parse_url($this->url, PHP_URL_HOST);
        $port = parse_url($this->url, PHP_URL_PORT);

        return 'https://'.(is_string($host) ? $host : '').(is_int($port) ? ':'.$port : '').'/…';
    }

    /** @return array<string, string> Nothing: the URL and key are replaced, never shown. */
    public function editable(): array
    {
        return [];
    }

    /**
     * @param ChannelConfiguration $other Configuration compared field by field.
     * @return bool Whether both target the same endpoint with the same key.
     */
    public function sameAs(ChannelConfiguration $other): bool
    {
        return $other instanceof self && hash_equals($other->url, $this->url) && hash_equals($other->signingSecret, $this->signingSecret);
    }

    /**
     * @param string $signingSecret Replacement key.
     * @return self Same endpoint signed with the new key.
     */
    public function withSigningSecret(string $signingSecret): self
    {
        return new self($this->url, $signingSecret);
    }
}
